#!/usr/bin/env python3
"""A small, dependency-free Parquet terminal viewer compatible with parqeye's CLI/TUI.

This is an original implementation built from observed behavior.  It implements enough
of the Parquet thrift metadata and common page encodings to inspect ordinary files and
render a ratatui-like interface in a terminal.
"""
from __future__ import annotations

import curses
import datetime as _dt
import decimal
import errno
import math
import os
import struct
import sys
import locale
