import ctypes
import ctypes.util
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

VERSION = "parqeye 0.0.2"
ABOUT = "Command line tool to visualize parquet files"
USAGE = "Usage: executable <PATH>"

# Thrift compact protocol type IDs
T_STOP = 0
T_TRUE = 1
T_FALSE = 2
T_BYTE = 3
T_I16 = 4
T_I32 = 5
T_I64 = 6
T_DOUBLE = 7
T_BINARY = 8
T_LIST = 9
T_SET = 10
T_MAP = 11
T_STRUCT = 12

TYPE_NAMES = {
    0: "BOOLEAN",
    1: "INT32",
    2: "INT64",
    3: "INT96",
    4: "FLOAT",
    5: "DOUBLE",
    6: "BYTE_ARRAY",
    7: "FIXED_LEN_BYTE_ARRAY",
}
REP_NAMES = {0: "REQUIRED", 1: "OPTIONAL", 2: "REPEATED", None: "REQUIRED"}
ENC_NAMES = {
    0: "PLAIN",
    1: "PLAIN_DICTIONARY",
    2: "RLE",
    3: "BIT_PACKED",
    4: "DELTA_BINARY_PACKED",
    5: "DELTA_LENGTH_BYTE_ARRAY",
    6: "DELTA_BYTE_ARRAY",
    7: "RLE_DICTIONARY",
    8: "BYTE_STREAM_SPLIT",
}
CODEC_NAMES = {
    0: "UNCOMPRESSED",
    1: "SNAPPY",
    2: "GZIP",
    3: "LZO",
    4: "BROTLI",
    5: "LZ4",
    6: "ZSTD",
    7: "LZ4_RAW",
}
PAGE_DATA = 0
PAGE_INDEX = 1
PAGE_DICT = 2
PAGE_DATA_V2 = 3

CONVERTED_UTF8 = 0
CONVERTED_LIST = 3
CONVERTED_DECIMAL = 5
CONVERTED_DATE = 6
CONVERTED_TIME_MILLIS = 7
CONVERTED_TIME_MICROS = 8
CONVERTED_TIMESTAMP_MILLIS = 9
CONVERTED_TIMESTAMP_MICROS = 10
CONVERTED_UINT_8 = 11
CONVERTED_UINT_16 = 12
CONVERTED_UINT_32 = 13
CONVERTED_UINT_64 = 14
CONVERTED_INT_8 = 15
CONVERTED_INT_16 = 16
CONVERTED_INT_32 = 17
CONVERTED_INT_64 = 18
CONVERTED_JSON = 19
CONVERTED_BSON = 20


class ParquetError(Exception):
    pass


class CompactReader:
    def __init__(self, data: bytes, pos: int = 0):
        self.data = data
        self.pos = pos
        self._last_stack: List[int] = [0]

    def tell(self) -> int:
        return self.pos

    def read_byte(self) -> int:
        if self.pos >= len(self.data):
            raise EOFError("unexpected end of thrift data")
        b = self.data[self.pos]
        self.pos += 1
        return b

    def read_bytes(self, n: int) -> bytes:
        if self.pos + n > len(self.data):
            raise EOFError("unexpected end of thrift data")
        b = self.data[self.pos:self.pos+n]
        self.pos += n
        return b

    def read_uvarint(self) -> int:
        shift = 0
        result = 0
        while True:
            b = self.read_byte()
            result |= (b & 0x7F) << shift
            if not (b & 0x80):
                return result
            shift += 7
            if shift > 70:
                raise ValueError("varint too long")

    def read_zigzag(self) -> int:
        n = self.read_uvarint()
        return (n >> 1) ^ -(n & 1)

    def read_i32(self) -> int:
        return self.read_zigzag()

    def read_i64(self) -> int:
        return self.read_zigzag()

    def read_binary(self) -> bytes:
        n = self.read_uvarint()
        return self.read_bytes(n)

    def read_string(self) -> str:
        return self.read_binary().decode("utf-8", "replace")

    def push_struct(self):
        self._last_stack.append(0)

    def pop_struct(self):
        self._last_stack.pop()

    def read_field_begin(self) -> Tuple[int, int]:
        b = self.read_byte()
        ttype = b & 0x0F
        if ttype == T_STOP:
            return 0, T_STOP
        delta = (b & 0xF0) >> 4
        if delta:
            fid = self._last_stack[-1] + delta
        else:
            fid = self.read_i32()
        self._last_stack[-1] = fid
        return fid, ttype

    def read_list_begin(self) -> Tuple[int, int]:
        b = self.read_byte()
        size = (b & 0xF0) >> 4
        etype = b & 0x0F
        if size == 15:
            size = self.read_uvarint()
        return etype, size

    def skip(self, ttype: int):
        if ttype in (T_TRUE, T_FALSE):
            return
        if ttype == T_BYTE:
            self.read_byte(); return
        if ttype in (T_I16, T_I32, T_I64):
            self.read_zigzag(); return
        if ttype == T_DOUBLE:
            self.read_bytes(8); return
        if ttype == T_BINARY:
            self.read_binary(); return
        if ttype in (T_LIST, T_SET):
            et, n = self.read_list_begin()
            for _ in range(n):
                self.skip(et)
            return
        if ttype == T_MAP:
            # Compact map: size varint; if nonzero, one byte key/value types.
            n = self.read_uvarint()
            if n:
                kv = self.read_byte(); kt = (kv & 0xF0) >> 4; vt = kv & 0x0F
                for _ in range(n):
                    self.skip(kt); self.skip(vt)
            return
        if ttype == T_STRUCT:
            self.push_struct()
            while True:
                fid, ft = self.read_field_begin()
                if ft == T_STOP:
                    break
                self.skip(ft)
            self.pop_struct()
            return
        raise ValueError(f"unknown thrift type {ttype}")


def read_bool_field(ttype: int, reader: CompactReader) -> bool:
    if ttype == T_TRUE:
        return True
    if ttype == T_FALSE:
        return False
    if ttype == T_BYTE:
        return bool(reader.read_byte())
    raise ValueError("not a bool field")


