def parse_logical_type(r: CompactReader) -> LogicalType:
    lt = LogicalType()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP:
            break
        if fid == 1 and ft == T_STRUCT:  # STRING
            lt.kind = "STRING"; r.skip(ft)
        elif fid == 3 and ft == T_STRUCT:  # LIST
            lt.kind = "LIST"; r.skip(ft)
        elif fid == 5 and ft == T_STRUCT:  # DECIMAL
            lt.kind = "DECIMAL"
            r.push_struct()
            while True:
                sfid, sft = r.read_field_begin()
                if sft == T_STOP: break
                if sfid == 1:
                    lt.scale = r.read_i32()
                elif sfid == 2:
                    lt.precision = r.read_i32()
                else:
                    r.skip(sft)
            r.pop_struct()
        elif fid == 6 and ft == T_STRUCT:
            lt.kind = "DATE"; r.skip(ft)
        elif fid == 7 and ft == T_STRUCT:  # TIME
            lt.kind = "TIME"; r.skip(ft)
        elif fid == 8 and ft == T_STRUCT:  # TIMESTAMP
            lt.kind = "TIMESTAMP"
            # We parse a few fields but tolerate layouts by skipping nested unit.
            r.push_struct()
            while True:
                sfid, sft = r.read_field_begin()
                if sft == T_STOP: break
                if sfid == 1:
                    lt.adjusted_to_utc = read_bool_field(sft, r)
                elif sfid == 2:
                    # TimeUnit is a union; note which subfield appears.
                    r.push_struct()
                    while True:
                        ufid, uft = r.read_field_begin()
                        if uft == T_STOP: break
                        lt.unit = {1: "MILLIS", 2: "MICROS", 3: "NANOS"}.get(ufid, lt.unit)
                        r.skip(uft)
                    r.pop_struct()
                else:
                    r.skip(sft)
            r.pop_struct()
        elif fid == 10 and ft == T_STRUCT:  # INTEGER
            lt.kind = "INTEGER"
            r.push_struct()
            while True:
                sfid, sft = r.read_field_begin()
                if sft == T_STOP: break
                if sfid == 1:
                    lt.bit_width = r.read_i32()
                elif sfid == 2:
                    lt.is_signed = read_bool_field(sft, r)
                else:
                    r.skip(sft)
            r.pop_struct()
        elif fid == 12 and ft == T_STRUCT:
            lt.kind = "JSON"; r.skip(ft)
        elif fid == 13 and ft == T_STRUCT:
            lt.kind = "BSON"; r.skip(ft)
        else:
            r.skip(ft)
    r.pop_struct()
    return lt


def parse_schema_element(r: CompactReader) -> SchemaElement:
    e = SchemaElement()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP:
            break
        if fid == 1:
            e.type = r.read_i32()
        elif fid == 2:
            e.type_length = r.read_i32()
        elif fid == 3:
            e.repetition_type = r.read_i32()
        elif fid == 4:
            e.name = r.read_string()
        elif fid == 5:
            e.num_children = r.read_i32()
        elif fid == 6:
            e.converted_type = r.read_i32()
        elif fid == 7:
            e.scale = r.read_i32()
        elif fid == 8:
            e.precision = r.read_i32()
        elif fid == 9:
            e.field_id = r.read_i32()
        elif fid == 10 and ft == T_STRUCT:
            e.logical = parse_logical_type(r)
        else:
            r.skip(ft)
    r.pop_struct()
    return e


def parse_statistics(r: CompactReader) -> Statistics:
    s = Statistics()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            s.max_value = r.read_binary()
        elif fid == 2:
            s.min_value = r.read_binary()
        elif fid == 3:
            s.null_count = r.read_i64()
        elif fid == 4:
            s.distinct_count = r.read_i64()
        elif fid == 5:
            s.max_value = r.read_binary()
        elif fid == 6:
            s.min_value = r.read_binary()
        else:
            r.skip(ft)
    r.pop_struct()
    return s


def parse_encoding_stat(r: CompactReader) -> EncodingStat:
    es = EncodingStat()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            es.page_type = r.read_i32()
        elif fid == 2:
            es.encoding = r.read_i32()
        elif fid == 3:
            es.count = r.read_i32()
        else:
            r.skip(ft)
    r.pop_struct()
    return es


def parse_column_metadata(r: CompactReader) -> ColumnMetaData:
    m = ColumnMetaData()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            m.type = r.read_i32()
        elif fid == 2:
            et, n = r.read_list_begin(); m.encodings = [r.read_i32() for _ in range(n)]
        elif fid == 3:
            et, n = r.read_list_begin(); m.path_in_schema = [r.read_string() for _ in range(n)]
        elif fid == 4:
            m.codec = r.read_i32()
        elif fid == 5:
            m.num_values = r.read_i64()
        elif fid == 6:
            m.total_uncompressed_size = r.read_i64()
        elif fid == 7:
            m.total_compressed_size = r.read_i64()
        elif fid == 9:
            m.data_page_offset = r.read_i64()
        elif fid == 10:
            m.index_page_offset = r.read_i64()
        elif fid == 11:
            m.dictionary_page_offset = r.read_i64()
        elif fid == 12 and ft == T_STRUCT:
            m.statistics = parse_statistics(r)
        elif fid == 13:
            et, n = r.read_list_begin(); m.encoding_stats = [parse_encoding_stat(r) for _ in range(n)]
        else:
            r.skip(ft)
    r.pop_struct()
    return m


def parse_column_chunk(r: CompactReader) -> ColumnChunk:
    c = ColumnChunk()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            c.file_path = r.read_string()
        elif fid == 2:
            c.file_offset = r.read_i64()
        elif fid == 3 and ft == T_STRUCT:
            c.meta_data = parse_column_metadata(r)
        else:
            r.skip(ft)
    r.pop_struct()
    return c


def parse_row_group(r: CompactReader) -> RowGroup:
    rg = RowGroup()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            et, n = r.read_list_begin(); rg.columns = [parse_column_chunk(r) for _ in range(n)]
        elif fid == 2:
            rg.total_byte_size = r.read_i64()
        elif fid == 3:
            rg.num_rows = r.read_i64()
        elif fid == 6:
            rg.total_compressed_size = r.read_i64()
        elif fid == 7:
            rg.ordinal = r.read_i16() if hasattr(r, 'read_i16') else r.read_i32()
        else:
            r.skip(ft)
    r.pop_struct()
    return rg


def parse_key_value(r: CompactReader) -> Tuple[str, str]:
    key = ""; val = ""
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1: key = r.read_string()
        elif fid == 2: val = r.read_string()
        else: r.skip(ft)
    r.pop_struct()
    return key, val


def parse_file_metadata(buf: bytes) -> FileMetaData:
    r = CompactReader(buf)
    fm = FileMetaData()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1:
            fm.version = r.read_i32()
        elif fid == 2:
            et, n = r.read_list_begin(); fm.schema = [parse_schema_element(r) for _ in range(n)]
        elif fid == 3:
            fm.num_rows = r.read_i64()
        elif fid == 4:
            et, n = r.read_list_begin(); fm.row_groups = [parse_row_group(r) for _ in range(n)]
        elif fid == 5:
            et, n = r.read_list_begin();
            for _ in range(n):
                k, v = parse_key_value(r); fm.key_value_metadata[k] = v
        elif fid == 6:
            fm.created_by = r.read_string()
        else:
            r.skip(ft)
    r.pop_struct()
    return fm


def parse_data_page_header(r: CompactReader) -> DataPageHeader:
    h = DataPageHeader()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1: h.num_values = r.read_i32()
        elif fid == 2: h.encoding = r.read_i32()
        elif fid == 3: h.definition_level_encoding = r.read_i32()
        elif fid == 4: h.repetition_level_encoding = r.read_i32()
        elif fid == 5 and ft == T_STRUCT: h.statistics = parse_statistics(r)
        else: r.skip(ft)
    r.pop_struct()
    return h


def parse_data_page_header_v2(r: CompactReader) -> DataPageHeaderV2:
    h = DataPageHeaderV2()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1: h.num_values = r.read_i32()
        elif fid == 2: h.num_nulls = r.read_i32()
        elif fid == 3: h.num_rows = r.read_i32()
        elif fid == 4: h.encoding = r.read_i32()
        elif fid == 5: h.definition_levels_byte_length = r.read_i32()
        elif fid == 6: h.repetition_levels_byte_length = r.read_i32()
        elif fid == 7: h.is_compressed = read_bool_field(ft, r)
        elif fid == 8 and ft == T_STRUCT: h.statistics = parse_statistics(r)
        else: r.skip(ft)
    r.pop_struct()
    return h


def parse_dict_page_header(r: CompactReader) -> DictPageHeader:
    h = DictPageHeader()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1: h.num_values = r.read_i32()
        elif fid == 2: h.encoding = r.read_i32()
        elif fid == 3: h.is_sorted = read_bool_field(ft, r)
        else: r.skip(ft)
    r.pop_struct()
    return h


def parse_page_header(data: bytes, pos: int) -> Tuple[PageHeader, int]:
    r = CompactReader(data, pos)
    h = PageHeader()
    r.push_struct()
    while True:
        fid, ft = r.read_field_begin()
        if ft == T_STOP: break
        if fid == 1: h.type = r.read_i32()
        elif fid == 2: h.uncompressed_page_size = r.read_i32()
        elif fid == 3: h.compressed_page_size = r.read_i32()
        elif fid == 5 and ft == T_STRUCT: h.data_page_header = parse_data_page_header(r)
        elif fid == 7 and ft == T_STRUCT: h.dictionary_page_header = parse_dict_page_header(r)
        elif fid == 8 and ft == T_STRUCT: h.data_page_header_v2 = parse_data_page_header_v2(r)
        else: r.skip(ft)
    r.pop_struct()
    return h, r.tell()


def read_parquet_file(path: str) -> Tuple[bytes, FileMetaData]:
    try:
        data = open(path, 'rb').read()
    except OSError as e:
        raise e
    if len(data) < 8:
        raise ParquetError("Invalid Parquet file. Corrupt footer")
    tail_magic = data[-4:]
    if tail_magic == b'PARE':
        raise ParquetError("Parquet file has an encrypted footer but the encryption feature is disabled")
    if tail_magic != b'PAR1':
        raise ParquetError("Invalid Parquet file. Corrupt footer")
    meta_len = struct.unpack('<I', data[-8:-4])[0]
    if meta_len < 0 or meta_len > len(data) - 8:
        raise ParquetError("Invalid Parquet file. Corrupt footer")
    meta_buf = data[len(data)-8-meta_len:len(data)-8]
    return data, parse_file_metadata(meta_buf)


# ---------------------------------------------------------------------------
# Compression helpers

def snappy_decompress(src: bytes, expected: Optional[int] = None) -> bytes:
    pos = 0
    shift = 0
    length = 0
    while True:
        if pos >= len(src):
            raise ParquetError("Snappy decompression failed")
        b = src[pos]; pos += 1
        length |= (b & 0x7f) << shift
        if not (b & 0x80):
            break
        shift += 7
    out = bytearray()
    while pos < len(src):
        tag = src[pos]; pos += 1
        typ = tag & 0x03
        if typ == 0:
            lcode = tag >> 2
            if lcode < 60:
                n = lcode + 1
            else:
                nb = lcode - 59
                n = int.from_bytes(src[pos:pos+nb], 'little') + 1
                pos += nb
            out.extend(src[pos:pos+n]); pos += n
        elif typ == 1:
            n = ((tag >> 2) & 0x7) + 4
            if pos >= len(src): raise ParquetError("Snappy decompression failed")
            off = ((tag & 0xE0) << 3) | src[pos]; pos += 1
            for _ in range(n):
                out.append(out[-off])
        elif typ == 2:
            n = (tag >> 2) + 1
            off = int.from_bytes(src[pos:pos+2], 'little'); pos += 2
            for _ in range(n): out.append(out[-off])
        else:
            n = (tag >> 2) + 1
            off = int.from_bytes(src[pos:pos+4], 'little'); pos += 4
            for _ in range(n): out.append(out[-off])
    # Some writers put the size in the snappy block; trust output even if expected differs.
    return bytes(out)


def _ctypes_zstd(src: bytes, expected: int) -> bytes:
    libname = ctypes.util.find_library('zstd') or 'libzstd.so.1'
    lib = ctypes.CDLL(libname)
    lib.ZSTD_decompress.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
    lib.ZSTD_decompress.restype = ctypes.c_size_t
    out = ctypes.create_string_buffer(max(0, expected))
    inp = ctypes.create_string_buffer(src)
    res = lib.ZSTD_decompress(out, expected, inp, len(src))
    # ZSTD_isError returns unsigned int
    try:
        lib.ZSTD_isError.argtypes = [ctypes.c_size_t]; lib.ZSTD_isError.restype = ctypes.c_uint
        if lib.ZSTD_isError(res):
            raise ParquetError("ZSTD decompression failed")
    except AttributeError:
        pass
    return out.raw[:res]


def _ctypes_lz4(src: bytes, expected: int) -> bytes:
    libname = ctypes.util.find_library('lz4') or 'liblz4.so.1'
    lib = ctypes.CDLL(libname)
    lib.LZ4_decompress_safe.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int, ctypes.c_int]
    lib.LZ4_decompress_safe.restype = ctypes.c_int
    out = ctypes.create_string_buffer(max(0, expected))
    res = lib.LZ4_decompress_safe(ctypes.c_char_p(src), out, len(src), expected)
    if res < 0:
        raise ParquetError("LZ4 decompression failed")
    return out.raw[:res]


def decompress_page(codec: int, payload: bytes, expected_uncompressed: int) -> bytes:
    if codec == 0:
        return payload
    if codec == 1:
        return snappy_decompress(payload, expected_uncompressed)
    if codec == 2:
        return zlib.decompress(payload, 16 + zlib.MAX_WBITS)
    if codec == 6:
        return _ctypes_zstd(payload, expected_uncompressed)
    if codec in (5, 7):
        # Most modern Parquet LZ4 data uses raw block compression.  If an older
        # hadoop-framed block appears, this may fail; metadata and schema still work.
        return _ctypes_lz4(payload, expected_uncompressed)
    raise ParquetError(f"Unsupported compression codec: {CODEC_NAMES.get(codec, codec)}")


# ---------------------------------------------------------------------------
# Encoding helpers

def uvarint_from(buf: bytes, pos: int) -> Tuple[int, int]:
    shift = 0; result = 0
    while True:
        if pos >= len(buf): raise EOFError("varint")
        b = buf[pos]; pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80): return result, pos
        shift += 7


def zigzag_decode(n: int) -> int:
    return (n >> 1) ^ -(n & 1)


def bit_width(max_value: int) -> int:
    if max_value <= 0: return 0
    return max_value.bit_length()


def unpack_bits_lsb(buf: bytes, bitw: int, count: int, pos: int = 0) -> Tuple[List[int], int]:
    if bitw == 0:
        return [0] * count, pos
    vals: List[int] = []
    bitpos = pos * 8
    total_bits = len(buf) * 8
    mask = (1 << bitw) - 1
    for _ in range(count):
        if bitpos + bitw > total_bits:
            break
        val = 0
        for j in range(bitw):
            byte = buf[(bitpos + j) // 8]
            if byte & (1 << ((bitpos + j) % 8)):
                val |= 1 << j
        vals.append(val & mask)
        bitpos += bitw
    return vals, (bitpos + 7) // 8


def decode_bitpacked_only(buf: bytes, bitw: int, count: int) -> Tuple[List[int], int]:
    return unpack_bits_lsb(buf, bitw, count, 0)


def decode_rle_hybrid(buf: bytes, bitw: int, count: Optional[int] = None, pos: int = 0, limit: Optional[int] = None) -> Tuple[List[int], int]:
    vals: List[int] = []
    end = len(buf) if limit is None else min(len(buf), pos + limit)
    bytew = (bitw + 7) // 8
    while pos < end and (count is None or len(vals) < count):
        header, pos = uvarint_from(buf, pos)
        if header & 1 == 0:
            run_len = header >> 1
            if bytew:
                if pos + bytew > end: break
                val = int.from_bytes(buf[pos:pos+bytew], 'little')
                pos += bytew
            else:
                val = 0
            need = run_len if count is None else min(run_len, count - len(vals))
            vals.extend([val] * need)
        else:
            groups = header >> 1
            n = groups * 8
            nbytes = (n * bitw + 7) // 8
            chunk = buf[pos:pos+nbytes]
            got, _ = unpack_bits_lsb(chunk, bitw, n, 0)
            need = len(got) if count is None else min(len(got), count - len(vals))
            vals.extend(got[:need])
            pos += nbytes
    return vals, pos


def decode_delta_binary_packed(buf: bytes, count: Optional[int] = None) -> Tuple[List[int], int]:
    pos = 0
    block_size, pos = uvarint_from(buf, pos)
    num_mini, pos = uvarint_from(buf, pos)
    total_count, pos = uvarint_from(buf, pos)
    first_u, pos = uvarint_from(buf, pos)
    first = zigzag_decode(first_u)
    if count is not None:
        total_count = min(total_count, count)
    if total_count == 0:
        return [], pos
    vals = [first]
    mini_size = block_size // max(1, num_mini)
    while len(vals) < total_count and pos < len(buf):
        md_u, pos = uvarint_from(buf, pos)
        min_delta = zigzag_decode(md_u)
        widths = list(buf[pos:pos+num_mini]); pos += num_mini
        for bw in widths:
            n = min(mini_size, total_count - len(vals))
            if n <= 0:
                # Still skip full miniblock bytes? Normally absent at end after needed.
                continue
            raw_count = mini_size
            nbytes = (raw_count * bw + 7) // 8
            chunk = buf[pos:pos+nbytes]; pos += nbytes
            deltas, _ = unpack_bits_lsb(chunk, bw, raw_count, 0)
            prev = vals[-1]
            for d in deltas[:n]:
                prev = prev + min_delta + d
                vals.append(prev)
                if len(vals) >= total_count:
                    break
    return vals[:total_count], pos


def decode_delta_length_byte_array(buf: bytes, count: int) -> Tuple[List[bytes], int]:
    lengths, pos = decode_delta_binary_packed(buf, count)
    out: List[bytes] = []
    for ln in lengths[:count]:
        if ln < 0: ln = 0
        out.append(buf[pos:pos+ln]); pos += ln
    return out, pos


def decode_delta_byte_array(buf: bytes, count: int) -> Tuple[List[bytes], int]:
    prefixes, pos = decode_delta_binary_packed(buf, count)
    suffixes, used = decode_delta_length_byte_array(buf[pos:], count)
    pos += used
    out: List[bytes] = []
    prev = b''
    for p, s in zip(prefixes, suffixes):
        if p < 0: p = 0
        val = prev[:p] + s
        out.append(val)
        prev = val
    return out, pos


def decode_plain_values(buf: bytes, elem: SchemaElement, count: int, type_override: Optional[int] = None) -> Tuple[List[Any], int]:
    typ = elem.type if type_override is None else type_override
    pos = 0
    vals: List[Any] = []
    if count <= 0:
        return vals, pos
    try:
        if typ == 0:  # BOOLEAN bit-packed
            vals, pos = unpack_bits_lsb(buf, 1, count, 0)
            vals = [bool(v) for v in vals]
        elif typ == 1:  # INT32
            for _ in range(count):
                vals.append(struct.unpack_from('<i', buf, pos)[0]); pos += 4
        elif typ == 2:  # INT64
            for _ in range(count):
                vals.append(struct.unpack_from('<q', buf, pos)[0]); pos += 8
        elif typ == 3:  # INT96
            for _ in range(count):
                vals.append(buf[pos:pos+12]); pos += 12
        elif typ == 4:  # FLOAT
            for _ in range(count):
                vals.append(struct.unpack_from('<f', buf, pos)[0]); pos += 4
        elif typ == 5:  # DOUBLE
            for _ in range(count):
                vals.append(struct.unpack_from('<d', buf, pos)[0]); pos += 8
        elif typ == 6:  # BYTE_ARRAY
            for _ in range(count):
                ln = struct.unpack_from('<I', buf, pos)[0]; pos += 4
                vals.append(buf[pos:pos+ln]); pos += ln
        elif typ == 7:  # FIXED_LEN_BYTE_ARRAY
            ln = elem.type_length or 0
            for _ in range(count):
                vals.append(buf[pos:pos+ln]); pos += ln
        else:
            vals = [None] * count
    except Exception:
        # Truncated or malformed pages: return what we have, mirroring a best-effort viewer.
        pass
    return vals, pos


def decode_byte_stream_split(buf: bytes, elem: SchemaElement, count: int) -> Tuple[List[Any], int]:
    typ = elem.type
    size = 4 if typ in (1, 4) else 8 if typ in (2, 5) else (elem.type_length or 0)
    total = size * count
    data = buf[:total]
    vals = []
    for i in range(count):
        b = bytes(data[i + j*count] for j in range(size))
        if typ == 4:
            vals.append(struct.unpack('<f', b)[0])
        elif typ == 5:
            vals.append(struct.unpack('<d', b)[0])
        elif typ == 1:
            vals.append(struct.unpack('<i', b)[0])
        elif typ == 2:
            vals.append(struct.unpack('<q', b)[0])
        else:
            vals.append(b)
    return vals, total


@dataclass
class LeafInfo:
    node: Node
    path_nodes: List[Node]
    max_def: int
    max_rep: int


def build_schema_tree(schema: List[SchemaElement]) -> Tuple[Node, List[Node]]:
    if not schema:
        root = Node(SchemaElement(name="root", num_children=0), 0)
        return root, []
    leaf_nodes: List[Node] = []
    def rec(idx: int, parent: Optional[Node]) -> Tuple[Node, int]:
        node = Node(schema[idx], idx, [], parent)
        next_idx = idx + 1
        for _ in range(schema[idx].num_children or 0):
            ch, next_idx = rec(next_idx, node)
            node.children.append(ch)
        if not node.children:
            node.leaf_index = len(leaf_nodes); leaf_nodes.append(node)
        return node, next_idx
    return rec(0, None)[0], leaf_nodes


def path_to_root(node: Node) -> List[Node]:
    p = []
    while node is not None:
        p.append(node); node = node.parent
    return list(reversed(p))


def leaf_infos(root: Node, leaves: List[Node]) -> List[LeafInfo]:
    infos: List[LeafInfo] = []
    for leaf in leaves:
        nodes = path_to_root(leaf)[1:]  # skip root
        md = sum(1 for n in nodes if n.elem.repetition_type in (1, 2))
        mr = sum(1 for n in nodes if n.elem.repetition_type == 2)
        infos.append(LeafInfo(leaf, nodes, md, mr))
    return infos


def is_string_elem(e: SchemaElement) -> bool:
    return (e.logical and e.logical.kind in ("STRING", "JSON")) or e.converted_type in (CONVERTED_UTF8, CONVERTED_JSON)


def is_decimal_elem(e: SchemaElement) -> bool:
    return (e.logical and e.logical.kind == "DECIMAL") or e.converted_type == CONVERTED_DECIMAL


def is_list_node(n: Node) -> bool:
    e = n.elem
    return (e.logical and e.logical.kind == "LIST") or e.converted_type == CONVERTED_LIST or (len(n.children) == 1 and n.children[0].elem.repetition_type == 2 and n.children[0].elem.name in ("list", "array"))


def decode_values_by_encoding(enc: int, buf: bytes, elem: SchemaElement, count: int, dictionary: Optional[List[Any]]) -> Tuple[List[Any], int]:
    if count <= 0:
        return [], 0
    if enc in (0,):
        return decode_plain_values(buf, elem, count)
    if enc in (1, 7):  # dictionary encoded data page
        if not buf:
            return [], 0
        bw = buf[0]
        idxs, pos = decode_rle_hybrid(buf, bw, count, 1)
        if dictionary is None:
            return idxs, pos
        vals = [dictionary[i] if 0 <= i < len(dictionary) else None for i in idxs[:count]]
        return vals, pos
    if enc == 2:  # RLE values, used mostly for booleans
        bw = 1 if elem.type == 0 else bit_width(count)
        vals, pos = decode_rle_hybrid(buf, bw, count, 0)
        if elem.type == 0:
            vals = [bool(v) for v in vals]
        return vals, pos
    if enc == 3:  # BIT_PACKED booleans/levels
        bw = 1 if elem.type == 0 else bit_width(count)
        vals, pos = decode_bitpacked_only(buf, bw, count)
        if elem.type == 0:
            vals = [bool(v) for v in vals]
        return vals, pos
    if enc == 4:
        vals, pos = decode_delta_binary_packed(buf, count)
        return vals, pos
    if enc == 5:
        return decode_delta_length_byte_array(buf, count)
    if enc == 6:
        return decode_delta_byte_array(buf, count)
    if enc == 8:
        return decode_byte_stream_split(buf, elem, count)
    return [None] * count, 0


def decode_column(data: bytes, rg: RowGroup, col_index: int, elem: SchemaElement, info: LeafInfo) -> Tuple[List[Tuple[int, int, Any]], List[Any]]:
    """Return level entries (rep, def, value) and flat row values for max_rep==0."""
    if col_index >= len(rg.columns) or rg.columns[col_index].meta_data is None:
        return [], []
    meta = rg.columns[col_index].meta_data
    start = meta.dictionary_page_offset if meta.dictionary_page_offset is not None else meta.data_page_offset
    if not start:
        start = rg.columns[col_index].file_offset
    pos = int(start)
    decoded_level_values = 0
    dictionary: Optional[List[Any]] = None
    entries: List[Tuple[int, int, Any]] = []
    # Safety guard for malformed offsets.
    max_pos = min(len(data), pos + max(meta.total_compressed_size + 65536, meta.total_compressed_size * 3 + 1024))
    while pos < len(data) and decoded_level_values < meta.num_values:
        try:
            ph, body_pos = parse_page_header(data, pos)
        except Exception:
            break
        body_end = body_pos + ph.compressed_page_size
        if body_end > len(data):
            break
        payload = data[body_pos:body_end]
        pos = body_end
        try:
            if ph.type == PAGE_DICT and ph.dictionary_page_header:
                raw = decompress_page(meta.codec, payload, ph.uncompressed_page_size)
                dictionary, _ = decode_plain_values(raw, elem, ph.dictionary_page_header.num_values)
                continue
            if ph.type == PAGE_DATA and ph.data_page_header:
                h = ph.data_page_header
                raw = decompress_page(meta.codec, payload, ph.uncompressed_page_size)
                off = 0
                nvals = h.num_values
                if info.max_rep > 0:
                    bw = bit_width(info.max_rep)
                    if h.repetition_level_encoding == 3:
                        reps, used = decode_bitpacked_only(raw[off:], bw, nvals)
                    else:
                        reps, used = decode_rle_hybrid(raw, bw, nvals, off)
                    off = used
                else:
                    reps = [0] * nvals
                if info.max_def > 0:
                    bw = bit_width(info.max_def)
                    if h.definition_level_encoding == 3:
                        defs, used2 = decode_bitpacked_only(raw[off:], bw, nvals); off += used2
                    else:
                        defs, used_abs = decode_rle_hybrid(raw, bw, nvals, off); off = used_abs
                else:
                    defs = [0] * nvals
                present = sum(1 for d in defs if d == info.max_def)
                vals, usedv = decode_values_by_encoding(h.encoding, raw[off:], elem, present, dictionary)
                vi = 0
                for rp, df in zip(reps, defs):
                    if df == info.max_def and vi < len(vals):
                        entries.append((rp, df, vals[vi])); vi += 1
                    else:
                        entries.append((rp, df, None))
                decoded_level_values += nvals
            elif ph.type == PAGE_DATA_V2 and ph.data_page_header_v2:
                h = ph.data_page_header_v2
                off = 0
                rep_bytes = payload[off:off+h.repetition_levels_byte_length]; off += h.repetition_levels_byte_length
                def_bytes = payload[off:off+h.definition_levels_byte_length]; off += h.definition_levels_byte_length
                value_payload = payload[off:]
                if info.max_rep > 0:
                    reps, _ = decode_rle_hybrid(rep_bytes, bit_width(info.max_rep), h.num_values, 0)
                else:
                    reps = [0] * h.num_values
                if info.max_def > 0:
                    defs, _ = decode_rle_hybrid(def_bytes, bit_width(info.max_def), h.num_values, 0)
                else:
                    defs = [0] * h.num_values
                present = sum(1 for d in defs if d == info.max_def)
                if h.is_compressed:
                    expected = max(0, ph.uncompressed_page_size - h.definition_levels_byte_length - h.repetition_levels_byte_length)
                    value_raw = decompress_page(meta.codec, value_payload, expected)
                else:
                    value_raw = value_payload
                vals, _ = decode_values_by_encoding(h.encoding, value_raw, elem, present, dictionary)
                vi = 0
                for rp, df in zip(reps, defs):
                    if df == info.max_def and vi < len(vals):
                        entries.append((rp, df, vals[vi])); vi += 1
                    else:
                        entries.append((rp, df, None))
                decoded_level_values += h.num_values
            # Ignore indexes and unknown page types.
        except Exception:
            # Stop decoding this column; metadata views remain useful.
            break
        if pos > max_pos and decoded_level_values == 0:
            break
    # Convert to flat row values for non-repeated columns.
    rows: List[Any] = []
    if info.max_rep == 0:
        for _rp, df, v in entries:
            rows.append(v if df == info.max_def else None)
        # Some required columns in old files may not have entries due to BIT_PACKED ambiguity; pad.
        if len(rows) < rg.num_rows:
            rows.extend([None] * (rg.num_rows - len(rows)))
    return entries, rows


def decode_all_columns(data: bytes, fm: FileMetaData, root: Node, leaves: List[Node]) -> Tuple[List[List[Tuple[int,int,Any]]], List[List[Any]]]:
    infos = leaf_infos(root, leaves)
    all_entries = [[] for _ in leaves]
    flat_values = [[] for _ in leaves]
    for rg in fm.row_groups:
        for i, leaf in enumerate(leaves):
            ent, rows = decode_column(data, rg, i, leaf.elem, infos[i])
            all_entries[i].extend(ent)
            flat_values[i].extend(rows)
    return all_entries, flat_values


# ---------------------------------------------------------------------------
# Formatting and high-level table model

def human_bytes(n: Optional[int]) -> str:
    if n is None:
        return "0 B"
    n = int(n)
    units = ["B", "KiB", "MiB", "GiB", "TiB"]
    val = float(n)
    for u in units:
        if abs(val) < 1024 or u == units[-1]:
            if u == "B": return f"{int(val)} B"
            return f"{val:.1f} {u}"
        val /= 1024.0


def ratio_str(uncompressed: int, compressed: int) -> str:
    if compressed == 0:
        return "0.00x"
    return f"{(uncompressed / compressed):.2f}x"


def julian_to_date(jd: int) -> Tuple[int, int, int]:
    # Fliegel & Van Flandern algorithm.
    l = jd + 68569
    n = (4 * l) // 146097
    l = l - (146097 * n + 3) // 4
    i = (4000 * (l + 1)) // 1461001
    l = l - (1461 * i) // 4 + 31
    j = (80 * l) // 2447
    day = l - (2447 * j) // 80
    l = j // 11
    month = j + 2 - 12 * l
    year = 100 * (n - 49) + i + l
    return year, month, day


def format_bytes_literal(b: bytes) -> str:
    parts = []
    for x in b:
        if x == 0x5c:
            parts.append('\\\\')
        elif x == 0x22:
            parts.append('\\"')
        elif 32 <= x <= 126:
            parts.append(chr(x))
        elif x == 9:
            parts.append('\\t')
        elif x == 10:
            parts.append('\\x0a')
        elif x == 13:
            parts.append('\\r')
        else:
            parts.append(f"\\x{x:02x}")
    return 'b"' + ''.join(parts) + '"'


def decimal_from_raw(v: Any, elem: SchemaElement) -> str:
    scale = elem.scale
    prec = elem.precision
    if elem.logical and elem.logical.kind == "DECIMAL":
        if elem.logical.scale is not None: scale = elem.logical.scale
        if elem.logical.precision is not None: prec = elem.logical.precision
    if scale is None: scale = 0
    if isinstance(v, (bytes, bytearray)):
        iv = int.from_bytes(bytes(v), 'big', signed=True)
    else:
        iv = int(v)
    d = decimal.Decimal(iv).scaleb(-int(scale))
    if scale > 0:
        return f"{d:.{scale}f}"
    return f"{d:.0f}"


def format_int96(v: bytes) -> str:
    if not isinstance(v, (bytes, bytearray)) or len(v) < 12:
        return str(v)
    nanos = int.from_bytes(v[:8], 'little', signed=False)
    jd = int.from_bytes(v[8:12], 'little', signed=False)
    y, m, d = julian_to_date(jd)
    sec = nanos // 1_000_000_000
    ns = nanos % 1_000_000_000
    hh = sec // 3600; mm = (sec % 3600) // 60; ss = sec % 60
    if ns:
        frac = f".{ns:09d}".rstrip('0')
    else:
        frac = ""
    return f"{y:04d}-{m:02d}-{d:02d} {hh:02d}:{mm:02d}:{ss:02d}{frac}"


def format_timestamp_from_int(v: int, unit: str) -> str:
    div = {'MILLIS': 1000, 'MICROS': 1_000_000, 'NANOS': 1_000_000_000}.get(unit, 1000)
    try:
        dt = _dt.datetime.utcfromtimestamp(v / div)
        if dt.microsecond:
            return dt.strftime('%Y-%m-%d %H:%M:%S.%f').rstrip('0').rstrip('.')
        return dt.strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return str(v)


def format_value(v: Any, elem: Optional[SchemaElement] = None) -> str:
    if v is None:
        return "NULL"
    if elem is not None and is_decimal_elem(elem):
        try: return decimal_from_raw(v, elem)
        except Exception: pass
    typ = elem.type if elem is not None else None
    conv = elem.converted_type if elem is not None else None
    logical = elem.logical.kind if elem is not None and elem.logical else ""
    if typ == 3 and isinstance(v, (bytes, bytearray)):
        return format_int96(bytes(v))
    if typ in (1, 2) and (conv == CONVERTED_DATE or logical == "DATE"):
        try:
            return (_dt.date(1970,1,1) + _dt.timedelta(days=int(v))).isoformat()
        except Exception:
            return str(v)
    if typ in (1, 2) and (conv in (CONVERTED_TIMESTAMP_MILLIS, CONVERTED_TIMESTAMP_MICROS) or logical == "TIMESTAMP"):
        unit = "MILLIS" if conv == CONVERTED_TIMESTAMP_MILLIS else "MICROS" if conv == CONVERTED_TIMESTAMP_MICROS else (elem.logical.unit if elem and elem.logical and elem.logical.unit else "MILLIS")
        return format_timestamp_from_int(int(v), unit)
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        if math.isnan(v): return "NaN"
        if math.isinf(v): return "inf" if v > 0 else "-inf"
        # Rust debug/display for simple floats is close to Python's general format, but
        # ensure a decimal point for whole float values.
        s = repr(float(v))
        return s
    if isinstance(v, (bytes, bytearray)):
        b = bytes(v)
        if elem is not None and is_string_elem(elem):
            try:
                s = b.decode('utf-8')
                return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
            except Exception:
                pass
        return format_bytes_literal(b)
    return str(v)


def truncate_cell(s: str, maxlen: int = 28) -> str:
    if len(s) <= maxlen:
        return s
    if maxlen <= 1:
        return "…"[:maxlen]
    return s[:maxlen-1] + "…"


def format_list(values: Optional[List[Any]], elem: SchemaElement) -> str:
    if values is None:
        return "NULL"
    parts = ["null" if x is None else format_value(x, elem) for x in values]
    if len(parts) > 3:
        parts = parts[:2] + ["…"] + parts[-1:]
    return "[" + ", ".join(parts) + "]"


def reconstruct_list(entries: List[Tuple[int,int,Any]], row_count: int, top: Node, leaf: Node, info: LeafInfo) -> List[Optional[List[Any]]]:
    # Definition level at which the list object itself is present.
    nodes = path_to_root(leaf)[1:]
    list_node_pos = 0
    for i, n in enumerate(nodes):
        if n is top:
            list_node_pos = i
            break
    list_def = sum(1 for n in nodes[:list_node_pos+1] if n.elem.repetition_type in (1,2))
    leaf_optional = leaf.elem.repetition_type == 1
    elem_null_def = info.max_def - 1 if leaf_optional and info.max_def > 0 else None
    rows: List[Optional[List[Any]]] = []
    current: Optional[List[Any]] = None
    have = False
    for rp, df, val in entries:
        if rp == 0:
            if have:
                rows.append(current)
            have = True
            if df < list_def:
                current = None
            else:
                current = []
        if not have:
            have = True; current = []
        if current is not None:
            if df == info.max_def:
                current.append(val)
            elif elem_null_def is not None and df == elem_null_def:
                current.append(None)
            # df == list_def means empty list marker.
    if have:
        rows.append(current)
    while len(rows) < row_count:
        rows.append(None)
    return rows[:row_count]


def first_leaf(node: Node) -> Optional[Node]:
    if node.is_leaf:
        return node
    for ch in node.children:
        fl = first_leaf(ch)
        if fl is not None: return fl
    return None


def collect_leaves(node: Node) -> List[Node]:
    if node.is_leaf: return [node]
    out: List[Node] = []
    for ch in node.children: out.extend(collect_leaves(ch))
    return out


@dataclass
class DisplayTable:
    columns: List[str]
    elems: List[Optional[SchemaElement]]
    rows: List[List[str]]
    raw_columns: List[List[Any]]


def build_display_table(fm: FileMetaData, root: Node, leaves: List[Node], entries: List[List[Tuple[int,int,Any]]], flat: List[List[Any]]) -> DisplayTable:
    infos = leaf_infos(root, leaves)
    row_count = int(fm.num_rows)
    cols: List[str] = []
    elems: List[Optional[SchemaElement]] = []
    raw_cols: List[List[Any]] = []
    top_nodes = root.children if root.children else leaves
    leaf_to_i = {id(n): i for i, n in enumerate(leaves)}
    for top in top_nodes:
        cols.append(top.elem.name)
        if top.is_leaf:
            i = leaf_to_i.get(id(top), top.leaf_index or 0)
            elem = top.elem
            elems.append(elem)
            vals = flat[i] if i < len(flat) else []
            vals = (vals + [None] * row_count)[:row_count]
            raw_cols.append(vals)
        elif is_list_node(top):
            lf = first_leaf(top)
            if lf is not None and lf.leaf_index is not None:
                i = lf.leaf_index
                vals = reconstruct_list(entries[i], row_count, top, lf, infos[i])
                elems.append(lf.elem)
                raw_cols.append(vals)
            else:
                elems.append(None); raw_cols.append([None]*row_count)
        else:
            # Struct-like: combine leaf child values for a compact brace display.
            struct_leaves = collect_leaves(top)
            elems.append(None)
            combined: List[Any] = []
            for r in range(row_count):
                vals = []
                for lf in struct_leaves:
                    if lf.leaf_index is not None and lf.leaf_index < len(flat):
                        col = flat[lf.leaf_index]
                        vals.append(col[r] if r < len(col) else None)
                combined.append(tuple(vals))
            raw_cols.append(combined)
    formatted_rows: List[List[str]] = []
    for r in range(row_count):
        row: List[str] = []
        for ci, vals in enumerate(raw_cols):
            elem = elems[ci]
            v = vals[r] if r < len(vals) else None
            if isinstance(v, list):
                row.append(format_list(v, elem or SchemaElement()))
            elif isinstance(v, tuple):
                parts = ["null" if x is None else format_value(x, None) for x in v]
                s = "{" + ",".join(parts) + "}"
                row.append(truncate_cell(s, 30))
            else:
                row.append(format_value(v, elem))
        formatted_rows.append(row)
    return DisplayTable(cols, elems, formatted_rows, raw_cols)


def codec_summary(fm: FileMetaData) -> str:
    counts: Dict[int, int] = {}
    for rg in fm.row_groups:
        for c in rg.columns:
            if c.meta_data:
                counts[c.meta_data.codec] = counts.get(c.meta_data.codec, 0) + 1
    return ", ".join(f"{CODEC_NAMES.get(k,k)}({v})" for k, v in sorted(counts.items(), key=lambda kv: kv[0]))


def encoding_summary(fm: FileMetaData) -> str:
    seen: List[int] = []
    for rg in fm.row_groups:
        for c in rg.columns:
            if c.meta_data:
                for e in c.meta_data.encodings:
                    if e not in seen: seen.append(e)
    # The original summary presents a stable, enum-like order for common encodings.
    order = [0, 1, 2, 3, 4, 5, 6, 7, 8]
    seen_sorted = [e for e in order if e in seen] + [e for e in seen if e not in order]
    return ", ".join(ENC_NAMES.get(e, str(e)) for e in seen_sorted)


def total_raw_compressed(fm: FileMetaData) -> Tuple[int, int]:
    raw = 0; comp = 0
    for rg in fm.row_groups:
        if rg.total_byte_size:
            raw += rg.total_byte_size
        else:
            raw += sum((c.meta_data.total_uncompressed_size if c.meta_data else 0) for c in rg.columns)
        if rg.total_compressed_size is not None:
            comp += rg.total_compressed_size
        else:
            comp += sum((c.meta_data.total_compressed_size if c.meta_data else 0) for c in rg.columns)
    return raw, comp


# ---------------------------------------------------------------------------
# TUI rendering

TABS = ["Visualize", "Metadata", "Schema", "Row Groups"]

@dataclass
class AppState:
    path: str
    data: bytes
    fm: FileMetaData
    root: Node
    leaves: List[Node]
    table: DisplayTable
    tab: int = 0
    row_offset: int = 0
    col_offset: int = 0
    schema_offset: int = 0
    schema_scroll_x: int = 0
    rg_index: int = 0


def safe_addstr(stdscr, y: int, x: int, s: str, attr: int = 0):
    try:
        h, w = stdscr.getmaxyx()
        if y < 0 or y >= h or x >= w:
            return
        if x < 0:
            s = s[-x:]; x = 0
        maxn = max(0, w - x)
        if maxn <= 0:
            return
        stdscr.addnstr(y, x, s, maxn, attr)
    except curses.error:
        pass


def draw_header(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    if w < 2: return
    yellow = curses.color_pair(3) if curses.has_colors() else 0
    green = curses.color_pair(2) if curses.has_colors() else 0
    safe_addstr(stdscr, 0, 0, "╭" + "─" * max(0, w-2) + "╮", yellow)
    inside_w = max(0, w - 2)
    left = " "
    for i, t in enumerate(TABS):
        left += t
        if i != len(TABS)-1:
            left += "   "
    path = app.path
    if len(path) > max(0, inside_w - 2):
        path = "…" + path[-(inside_w-3):]
    spaces = max(1, inside_w - len(left) - len(path))
    line = (left + " " * spaces + path)[:inside_w]
    line = line + " " * (inside_w - len(line))
    safe_addstr(stdscr, 1, 0, "│", yellow)
    # Draw line in pieces to highlight current tab in reverse; plain capture is unchanged.
    safe_addstr(stdscr, 1, 1, line)
    # Active tab approximate location
    tab_prefix = " " + "   ".join(TABS[:app.tab])
    if app.tab > 0: tab_prefix += "   "
    tx = 1 + len(tab_prefix)
    safe_addstr(stdscr, 1, tx, TABS[app.tab], curses.A_REVERSE)
    if len(path) <= inside_w:
        safe_addstr(stdscr, 1, 1 + inside_w - len(path), path, green)
    safe_addstr(stdscr, 1, w-1, "│", yellow)
    safe_addstr(stdscr, 2, 0, "╰" + "─" * max(0, w-2) + "╯", yellow)


def draw_footer(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    if h <= 0: return
    if app.tab == 0:
        helptext = "↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit"
    elif app.tab == 1:
        helptext = "[Tab] Next Tab, [Q]uit"
    elif app.tab == 2:
        helptext = "←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit"
    else:
        helptext = "→/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit"
    safe_addstr(stdscr, h-1, 0, "parqeye", curses.A_BOLD | (curses.color_pair(2) if curses.has_colors() else 0))
    x = max(8, w - len(helptext))
    safe_addstr(stdscr, h-1, x, helptext)


def compute_col_widths(table: DisplayTable) -> List[int]:
    widths: List[int] = []
    sample_rows = table.rows[:200]
    for i, name in enumerate(table.columns):
        maxv = len(name)
        for r in sample_rows:
            if i < len(r): maxv = max(maxv, len(r[i]))
        widths.append(max(10, min(40, maxv + 2)))
    return widths


def draw_visualize(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    table = app.table
    widths = compute_col_widths(table)
    max_col_offset = max(0, len(table.columns) - 1)
    app.col_offset = max(0, min(app.col_offset, max_col_offset))
    content_h = max(0, h - 5)
    visible_rows = max(0, h - 6)
    app.row_offset = max(0, min(app.row_offset, max(0, len(table.rows) - visible_rows)))
    header_y = 3
    if h <= 5: return
    # Header line
    x = 9
    for ci in range(app.col_offset, len(table.columns)):
        s = table.columns[ci]
        safe_addstr(stdscr, header_y, x, s[:max(0, w-x)])
        x += widths[ci]
        if x >= w: break
    sep = "─" * min(6, w) + ("┬" if w > 6 else "") + "─" * max(0, w-7)
    safe_addstr(stdscr, header_y+1, 0, sep, curses.color_pair(4) if curses.has_colors() else 0)
    y = header_y + 2
    for ri in range(app.row_offset, min(len(table.rows), app.row_offset + visible_rows)):
        safe_addstr(stdscr, y, 0, f"{ri+1:<6}", curses.color_pair(4) if curses.has_colors() else 0)
        safe_addstr(stdscr, y, 6, "│", curses.color_pair(4) if curses.has_colors() else 0)
        x = 9
        row = table.rows[ri]
        for ci in range(app.col_offset, len(table.columns)):
            val = row[ci] if ci < len(row) else "NULL"
            cell = truncate_cell(val, max(1, widths[ci]-2))
            attr = 0
            if ri == app.row_offset and ci == app.col_offset:
                attr = curses.A_BOLD
                if curses.has_colors(): attr |= curses.color_pair(5)
            safe_addstr(stdscr, y, x, cell, attr)
            x += widths[ci]
            if x >= w: break
        y += 1
    while y < h - 1:
        safe_addstr(stdscr, y, 6, "│", curses.color_pair(4) if curses.has_colors() else 0)
        y += 1


def draw_box(stdscr, y: int, x: int, height: int, width: int, title: str = "", footer: str = "", attr: int = 0):
    if height <= 1 or width <= 1: return
    top = "╭" + "─" * (width-2) + "╮"
    if title and width > len(title) + 4:
        start = max(1, (width - len(title)) // 2)
        top = top[:start] + title + top[start+len(title):]
    safe_addstr(stdscr, y, x, top, attr)
    for yy in range(y+1, y+height-1):
        safe_addstr(stdscr, yy, x, "│" + " "*(width-2) + "│", attr)
    bot = "╰" + "─" * (width-2) + "╯"
    if footer and width > len(footer) + 4:
        start = max(1, (width - len(footer)) // 2)
        bot = bot[:start] + footer + bot[start+len(footer):]
    safe_addstr(stdscr, y+height-1, x, bot, attr)


def draw_metadata(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    fm = app.fm
    raw, comp = total_raw_compressed(fm)
    lines = [
        ("Format version", str(fm.version)),
        ("Created by", fm.created_by or ""),
        ("Rows", str(fm.num_rows)),
        ("Columns", str(len(app.leaves))),
        ("Row groups", str(len(fm.row_groups))),
        ("Size (raw)", human_bytes(raw)),
        ("Size (compressed)", human_bytes(comp)),
        ("Compression ratio", ratio_str(raw, comp)),
        ("Codecs (cols)", codec_summary(fm)),
        ("Encodings", encoding_summary(fm)),
        ("Avg row size", human_bytes(raw // fm.num_rows if fm.num_rows else 0)),
    ]
    body = [f"{k:>18} {v}" for k, v in lines]
    bw = min(w, max(len(s) for s in body) + 4)
    bh = len(body) + 2
    x = max(0, (w - bw)//2)
    y = max(3, (h - 1 - bh)//2)
    draw_box(stdscr, y, x, bh, bw, "File Metadata", attr=curses.color_pair(3) if curses.has_colors() else 0)
    for i, s in enumerate(body):
        safe_addstr(stdscr, y+1+i, x+1, " " + s[:max(0,bw-3)])


def tree_lines(root: Node) -> List[Tuple[Node, str]]:
    out: List[Tuple[Node, str]] = []
    def rec(n: Node, prefix: str, is_last: bool):
        connector = "└─ " if is_last else "├─ "
        out.append((n, prefix + connector + n.elem.name))
        child_prefix = prefix + ("   " if is_last else "│  ")
        for i, ch in enumerate(n.children):
            rec(ch, child_prefix, i == len(n.children)-1)
    rec(root, "", True)
    return out


def column_meta_for_leaf(app: AppState, leaf: Node) -> Optional[ColumnMetaData]:
    idx = leaf.leaf_index
    if idx is None: return None
    # Aggregate first row group's metadata for per-column display (all bundled files have one RG).
    if app.fm.row_groups and idx < len(app.fm.row_groups[0].columns):
        return app.fm.row_groups[0].columns[idx].meta_data
    return None


def stat_line_for_node(app: AppState, node: Node) -> str:
    e = node.elem
    rep = REP_NAMES.get(e.repetition_type, "REQUIRED")
    if not node.is_leaf:
        return f"{rep:<11} {'group':<11}"
    m = column_meta_for_leaf(app, node)
    phys = TYPE_NAMES.get(e.type, "")
    if not m:
        return f"{rep:<11} {phys:<11}"
    comp = human_bytes(m.total_compressed_size)
    uncomp = human_bytes(m.total_uncompressed_size)
    ratio = ratio_str(m.total_uncompressed_size, m.total_compressed_size)
    encs = ", ".join(ENC_NAMES.get(x, str(x)) for x in m.encodings)
    codec = CODEC_NAMES.get(m.codec, str(m.codec))
    return f"{rep:<11} {phys:<11} {comp:<11} {uncomp:<13} {ratio:<6} {encs:<24} {codec:<12}"


def draw_schema(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    lines = tree_lines(app.root)
    max_tree = max((len(s) for _, s in lines), default=10)
    left_w = min(max(max_tree + 4, 24), max(24, w // 2 - 1))
    right_w = max(2, w - left_w)
    panel_h = max(3, h - 4)
    y0 = 3
    draw_box(stdscr, y0, 0, panel_h, left_w, "Schema Tree", "Leaf, Group", curses.color_pair(3) if curses.has_colors() else 0)
    # Right panel with square-ish corners in original is still fine with rounded.
    draw_box(stdscr, y0, left_w, panel_h, right_w, "Column Statistics", "", curses.color_pair(3) if curses.has_colors() else 0)
    content_h = panel_h - 2
    app.schema_offset = max(0, min(app.schema_offset, max(0, len(lines)-content_h)))
    for row in range(content_h):
        idx = app.schema_offset + row
        if idx < len(lines):
            node, s = lines[idx]
            attr = 0
            safe_addstr(stdscr, y0+1+row, 1, s[:left_w-2], attr)
    header = f"{'Repetition':<11} {'Physical':<11} {'Compressed':<11} {'Uncompressed':<13} {'Ratio':<6} {'Encodings':<24} {'Compression':<12}"
    stat_rows = [header] + [stat_line_for_node(app, n) for n, _s in lines[1:]]
    for row in range(content_h):
        idx = app.schema_offset + row
        if idx < len(stat_rows):
            s = stat_rows[idx]
            sx = app.schema_scroll_x
            safe_addstr(stdscr, y0+1+row, left_w+1, s[sx:sx+max(0,right_w-2)])


def draw_row_groups(stdscr, app: AppState):
    h, w = stdscr.getmaxyx()
    lines = tree_lines(app.root)
    max_tree = max((len(s) for _, s in lines), default=10)
    left_w = min(max(max_tree + 4, 23), max(23, w // 2 - 1))
    right_w = max(2, w - left_w)
    panel_h = max(3, h - 4)
    y0 = 3
    draw_box(stdscr, y0, 0, panel_h, left_w, "Schema Tree", "Leaf, Group", curses.color_pair(3) if curses.has_colors() else 0)
    content_h = panel_h - 2
    for row in range(content_h):
        idx = app.schema_offset + row
        if idx < len(lines):
            safe_addstr(stdscr, y0+1+row, 1, lines[idx][1][:left_w-2])
    nrg = max(1, len(app.fm.row_groups))
    app.rg_index = max(0, min(app.rg_index, nrg-1))
    rg = app.fm.row_groups[app.rg_index] if app.fm.row_groups else RowGroup(num_rows=0)
    # Top row-group progress box
    top_h = 3
    title = f" Row Group: {app.rg_index+1} / {nrg} "
    # Use ASCII-ish square corners here to resemble ratatui default block.
    x = left_w; y = y0; bw = right_w
    if bw > 2:
        safe_addstr(stdscr, y, x, "┌" + title + "─" * max(0, bw-2-len(title)) + "┐")
        bar = "█" * max(0, bw-2)
        safe_addstr(stdscr, y+1, x, "│" + bar[:bw-2] + "│")
        safe_addstr(stdscr, y+2, x, "└" + "─"*(bw-2) + "┘")
    raw, comp = total_raw_compressed(app.fm)
    rg_raw = rg.total_byte_size or sum((c.meta_data.total_uncompressed_size if c.meta_data else 0) for c in rg.columns)
    rg_comp = rg.total_compressed_size if rg.total_compressed_size is not None else sum((c.meta_data.total_compressed_size if c.meta_data else 0) for c in rg.columns)
    boxes = [
        ("Rows", f"{rg.num_rows}", f"{rg.num_rows} / {app.fm.num_rows}"),
        ("Compressed", human_bytes(rg_comp), f"{human_bytes(rg_comp)} / {human_bytes(comp)}"),
        ("Uncompressed", human_bytes(rg_raw), f"{human_bytes(rg_raw)} / {human_bytes(raw)}"),
        ("Ratio", f"{(rg_raw/rg_comp if rg_comp else 0):.2f}", f"{(rg_raw/rg_comp if rg_comp else 0):.2f} / {(raw/comp if comp else 0):.2f}"),
    ]
    by = y0 + 4
    bx = left_w
    gap = 1
    each = max(12, (right_w - 3*gap)//4)
    for i,(title,val,foot) in enumerate(boxes):
        xx = bx + i*(each+gap)
        ww = min(each, w-xx)
        if ww <= 4: continue
        safe_addstr(stdscr, by, xx, "┌" + title + "─"*max(0,ww-2-len(title)) + "┐")
        safe_addstr(stdscr, by+1, xx, "│" + val.center(max(0,ww-2))[:ww-2] + "│")
        safe_addstr(stdscr, by+2, xx, "└" + foot.center(max(0,ww-2), "─")[:ww-2] + "┘")
    chart_y = by + 4
    if chart_y < h-2:
        safe_addstr(stdscr, chart_y, left_w+10, "Compressed vs Uncompressed (B)")
        vals = [rg_comp or 0, rg_raw or 0]
        maxv = max(vals + [1])
        axis_x = left_w + 4
        for i in range(12):
            yy = chart_y + 1 + i
            if yy >= h-2: break
            safe_addstr(stdscr, yy, axis_x, "│")
        dot_y = chart_y + 1 + max(0, min(10, 10 - int((rg_comp/maxv)*10)))
        safe_addstr(stdscr, dot_y, min(w-2, left_w + right_w//2), "•")
        if chart_y + 13 < h-1:
            safe_addstr(stdscr, chart_y+12, axis_x, "└" + "─"*max(0, min(45, w-axis_x-1)))
            safe_addstr(stdscr, chart_y+14, left_w+1, "Row Group")


def draw_app(stdscr, app: AppState):
    stdscr.erase()
    draw_header(stdscr, app)
    if app.tab == 0: draw_visualize(stdscr, app)
    elif app.tab == 1: draw_metadata(stdscr, app)
    elif app.tab == 2: draw_schema(stdscr, app)
    else: draw_row_groups(stdscr, app)
    draw_footer(stdscr, app)
    stdscr.refresh()


def init_colors():
    if not curses.has_colors(): return
    curses.start_color()
    try: curses.use_default_colors()
    except Exception: pass
    curses.init_pair(1, curses.COLOR_WHITE, -1)
    curses.init_pair(2, curses.COLOR_GREEN, -1)
    curses.init_pair(3, curses.COLOR_YELLOW, -1)
    curses.init_pair(4, curses.COLOR_CYAN, -1)
    curses.init_pair(5, curses.COLOR_WHITE, curses.COLOR_BLACK)


def app_loop(stdscr, app: AppState):
    curses.curs_set(0)
    stdscr.keypad(True)
    stdscr.nodelay(False)
    init_colors()
    while True:
        draw_app(stdscr, app)
        try:
            ch = stdscr.getch()
        except KeyboardInterrupt:
            break
        if ch in (ord('q'), ord('Q'), 27):
            break
        if ch in (9,):
            app.tab = (app.tab + 1) % len(TABS)
        elif ch == curses.KEY_BTAB:
            app.tab = (app.tab - 1) % len(TABS)
        elif app.tab == 0:
            if ch == curses.KEY_RIGHT:
                app.col_offset = min(max(0, len(app.table.columns)-1), app.col_offset + 1)
            elif ch == curses.KEY_LEFT:
                app.col_offset = max(0, app.col_offset - 1)
            elif ch == curses.KEY_DOWN:
                app.row_offset = min(max(0, len(app.table.rows)-1), app.row_offset + 1)
            elif ch == curses.KEY_UP:
                app.row_offset = max(0, app.row_offset - 1)
            elif ch in (ord('d'), ord('D'), curses.KEY_NPAGE):
                h, _ = stdscr.getmaxyx(); app.row_offset = min(max(0, len(app.table.rows)-1), app.row_offset + max(1,h-6))
            elif ch in (ord('u'), ord('U'), curses.KEY_PPAGE):
                h, _ = stdscr.getmaxyx(); app.row_offset = max(0, app.row_offset - max(1,h-6))
        elif app.tab == 2:
            if ch == curses.KEY_RIGHT: app.schema_scroll_x += 2
            elif ch == curses.KEY_LEFT: app.schema_scroll_x = max(0, app.schema_scroll_x - 2)
            elif ch == curses.KEY_DOWN: app.schema_offset += 1
            elif ch == curses.KEY_UP: app.schema_offset = max(0, app.schema_offset - 1)
        elif app.tab == 3:
            if ch == curses.KEY_RIGHT: app.rg_index = min(max(0,len(app.fm.row_groups)-1), app.rg_index + 1)
            elif ch == curses.KEY_LEFT: app.rg_index = max(0, app.rg_index - 1)
            elif ch == curses.KEY_DOWN: app.schema_offset += 1
            elif ch == curses.KEY_UP: app.schema_offset = max(0, app.schema_offset - 1)


def build_app(path: str) -> AppState:
    data, fm = read_parquet_file(path)
    root, leaves = build_schema_tree(fm.schema)
    try:
        entries, flat = decode_all_columns(data, fm, root, leaves)
        table = build_display_table(fm, root, leaves, entries, flat)
    except Exception:
        table = DisplayTable([n.elem.name for n in (root.children or leaves)], [n.elem if n.is_leaf else None for n in (root.children or leaves)], [], [])
    return AppState(path, data, fm, root, leaves, table)


# ---------------------------------------------------------------------------
# CLI behavior

def print_help():
    print(ABOUT)
    print()
    print(USAGE)
    print()
    print("Arguments:")
    print("  <PATH>  Path to the parquet file")
    print()
    print("Options:")
    print("  -h, --help     Print help")
    print("  -V, --version  Print version")


def cli_error(msg: str, tip: Optional[str] = None):
    print(f"error: {msg}", file=sys.stderr)
    if tip:
        print(file=sys.stderr)
        print(f"  tip: {tip}", file=sys.stderr)
    print(file=sys.stderr)
    print(USAGE, file=sys.stderr)
    print(file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)


def parse_args(argv: List[str]) -> Optional[str]:
    # Clap treats help/version as global and successful even with other args.
    if any(a in ('-h', '--help') for a in argv):
        print_help(); sys.exit(0)
    if any(a in ('-V', '--version') for a in argv):
        print(VERSION); sys.exit(0)
    args: List[str] = []
    endopts = False
    for a in argv:
        if endopts:
            args.append(a)
        elif a == '--':
            endopts = True
        elif a.startswith('-'):
            cli_error(f"unexpected argument '{a}' found", f"to pass '{a}' as a value, use '-- {a}'")
            sys.exit(2)
        else:
            args.append(a)
    if not args:
        print("error: the following required arguments were not provided:", file=sys.stderr)
        print("  <PATH>", file=sys.stderr)
        print(file=sys.stderr)
        print(USAGE, file=sys.stderr)
        print(file=sys.stderr)
        print("For more information, try '--help'.", file=sys.stderr)
        sys.exit(2)
    if len(args) > 1:
        cli_error(f"unexpected argument '{args[1]}' found")
        sys.exit(2)
    return args[0]


def emit_non_tty_panic():
    # Observed ratatui init panic when stdout is not a terminal.
    sys.stdout.write('\x1b[?1049l')
    sys.stdout.flush()
    pid = os.getpid()
    print(file=sys.stderr)
    print(f"thread 'main' ({pid}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/ratatui-0.29.0/src/terminal/init.rs:52:16:", file=sys.stderr)
    print('failed to initialize terminal: Os { code: 6, kind: Uncategorized, message: "No such device or address" }', file=sys.stderr)
    print("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", file=sys.stderr)


def main(argv: List[str]) -> int:
    path = parse_args(argv)
    if path is None:
        return 0
    if not sys.stdout.isatty():
        emit_non_tty_panic()
        return 101
    # The original enters the alternate screen before attempting to open/parse.
    try:
        app = build_app(path)
    except OSError as e:
        sys.stdout.write('\x1b[?1049h')
        sys.stdout.write(f"Error: Custom {{ kind: Other, error: \"{e.strerror} (os error {e.errno})\" }}\n")
        sys.stdout.flush()
        return 1
    except ParquetError as e:
        sys.stdout.write('\x1b[?1049h')
        sys.stdout.write(f"Error: Custom {{ kind: Other, error: \"Parquet error: {e}\" }}\n")
        sys.stdout.flush()
        return 1
    except Exception as e:
        sys.stdout.write('\x1b[?1049h')
        sys.stdout.write(f"Error: Custom {{ kind: Other, error: \"{e}\" }}\n")
        sys.stdout.flush()
        return 1
    locale.setlocale(locale.LC_ALL, '')
    curses.wrapper(app_loop, app)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
