CONVERTED_UINT_32 = 13
CONVERTED_UINT_64 = 14
CONVERTED_INT_8 = 15
CONVERTED_INT_16 = 16
CONVERTED_INT_32 = 17
CONVERTED_INT_64 = 18
CONVERTED_JSON = 19
CONVERTED_BSON = 20


class ParquetError(Exception):
    pass


class CompactReader:
    def __init__(self, data: bytes, pos: int = 0):
        self.data = data
        self.pos = pos
        self._last_stack: List[int] = [0]

    def tell(self) -> int:
        return self.pos

    def read_byte(self) -> int:
        if self.pos >= len(self.data):
            raise EOFError("unexpected end of thrift data")
        b = self.data[self.pos]
        self.pos += 1
        return b

    def read_bytes(self, n: int) -> bytes:
        if self.pos + n > len(self.data):
            raise EOFError("unexpected end of thrift data")
        b = self.data[self.pos:self.pos+n]
        self.pos += n
        return b

    def read_uvarint(self) -> int:
        shift = 0
        result = 0
        while True:
            b = self.read_byte()
            result |= (b & 0x7F) << shift
            if not (b & 0x80):
                return result
            shift += 7
            if shift > 70:
                raise ValueError("varint too long")

    def read_zigzag(self) -> int:
        n = self.read_uvarint()
        return (n >> 1) ^ -(n & 1)

    def read_i32(self) -> int:
        return self.read_zigzag()

    def read_i64(self) -> int:
        return self.read_zigzag()

    def read_binary(self) -> bytes:
        n = self.read_uvarint()
        return self.read_bytes(n)

    def read_string(self) -> str:
        return self.read_binary().decode("utf-8", "replace")

    def push_struct(self):
        self._last_stack.append(0)

    def pop_struct(self):
        self._last_stack.pop()

    def read_field_begin(self) -> Tuple[int, int]:
        b = self.read_byte()
        ttype = b & 0x0F
        if ttype == T_STOP:
            return 0, T_STOP
        delta = (b & 0xF0) >> 4
        if delta:
            fid = self._last_stack[-1] + delta
        else:
            fid = self.read_i32()
        self._last_stack[-1] = fid
        return fid, ttype

    def read_list_begin(self) -> Tuple[int, int]:
        b = self.read_byte()
        size = (b & 0xF0) >> 4
        etype = b & 0x0F
        if size == 15:
            size = self.read_uvarint()
        return etype, size

    def skip(self, ttype: int):
        if ttype in (T_TRUE, T_FALSE):
            return
        if ttype == T_BYTE:
            self.read_byte(); return
        if ttype in (T_I16, T_I32, T_I64):
            self.read_zigzag(); return
        if ttype == T_DOUBLE:
            self.read_bytes(8); return
        if ttype == T_BINARY:
            self.read_binary(); return
        if ttype in (T_LIST, T_SET):
            et, n = self.read_list_begin()
            for _ in range(n):
                self.skip(et)
            return
        if ttype == T_MAP:
            # Compact map: size varint; if nonzero, one byte key/value types.
            n = self.read_uvarint()
            if n:
                kv = self.read_byte(); kt = (kv & 0xF0) >> 4; vt = kv & 0x0F
                for _ in range(n):
                    self.skip(kt); self.skip(vt)
            return
        if ttype == T_STRUCT:
            self.push_struct()
            while True:
                fid, ft = self.read_field_begin()
                if ft == T_STOP:
                    break
                self.skip(ft)
            self.pop_struct()
            return
        raise ValueError(f"unknown thrift type {ttype}")


def read_bool_field(ttype: int, reader: CompactReader) -> bool:
    if ttype == T_TRUE:
        return True
    if ttype == T_FALSE:
        return False
    if ttype == T_BYTE:
        return bool(reader.read_byte())
    raise ValueError("not a bool field")


